-- Issue #28616 removes ability to have duplicate UPC code so we are generating some random ones here
CREATE OR REPLACE FUNCTION randomUPCCode()
RETURNS TEXT AS $_$
  SELECT (random() * 1000 + 1000)::INTEGER||'-'||(random() * 100000 + 10000)::INTEGER;
$_$ language sql;


